// Generated by npm run build:web. Edit web/console/public instead.
export default {"/console/app.css":{"type":"text/css; charset=utf-8","body":":root { color-scheme: dark; }\nhtml, body {\n  margin: 0; height: 100%; background: #0b0c0f; color: #e8eaed;\n  font: 15px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", system-ui, sans-serif;\n  -webkit-text-size-adjust: 100%; overscroll-behavior: none; overflow: hidden;\n}\n.boot {\n  min-height: 100%; box-sizing: border-box; display: flex; flex-direction: column; align-items: center; justify-content: center;\n  gap: 10px; text-align: center;\n  padding: calc(24px + env(safe-area-inset-top)) calc(24px + env(safe-area-inset-right)) calc(24px + env(safe-area-inset-bottom)) calc(24px + env(safe-area-inset-left));\n}\n.boot img { border-radius: 18px; box-shadow: 0 12px 32px -12px rgba(45, 212, 191, 0.45); }\n.boot h1 { margin: 6px 0 0; font-size: 22px; font-weight: 650; letter-spacing: -0.02em; }\n.boot p { margin: 0; color: #9aa3ad; }\n.boot button {\n  min-height: 44px; padding: 0 20px; border-radius: 12px; border: 1px solid #2b313a; background: #171a20; color: #e8eaed;\n  font: inherit; font-weight: 600; cursor: pointer; touch-action: manipulation;\n}\n.boot button:focus-visible { outline: 2px solid #2dd4bf; outline-offset: 2px; }\n.install { margin-top: 18px; max-width: 340px; text-align: left; padding: 16px 18px; border-radius: 16px; border: 1px solid #23272f; background: #12151a; }\n.install h2 { margin: 0 0 8px; font-size: 16px; }\n.install ol { margin: 0 0 14px; padding-left: 20px; color: #c3c9d0; }\n.install li { margin: 4px 0; }\n.install button { width: 100%; }\n@media (prefers-reduced-motion: no-preference) {\n  .boot img { animation: boot-pulse 1.6s ease-in-out infinite; }\n  @keyframes boot-pulse { 50% { transform: scale(0.96); opacity: 0.85; } }\n}\n"},"/console/app.js":{"type":"text/javascript; charset=utf-8","body":"// Saints Service home-screen app: starts the same console script the\n// bookmarklet injects, in app mode (full screen, safe areas, no close).\n(function () {\n  'use strict';\n  window.__agentConsoleApp = true;\n  var boot = document.getElementById('boot');\n  var msg = document.getElementById('boot-msg');\n  var retry = document.getElementById('boot-retry');\n  var install = document.getElementById('install');\n\n  if ('serviceWorker' in navigator) {\n    navigator.serviceWorker.register('/console/sw.js', { scope: '/console/' }).catch(function () { /* app still works online */ });\n  }\n\n  // Opened from the Home Screen (iOS sets navigator.standalone) or as an\n  // installed app elsewhere. In Safari, iPhone users first see how to install.\n  var standalone = navigator.standalone === true ||\n    (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches);\n  var iPhoneSafari = /iP(hone|od|ad)/.test(navigator.userAgent) ||\n    (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);\n\n  function start() {\n    install.hidden = true;\n    retry.hidden = true;\n    msg.textContent = 'Loading…';\n    var s = document.createElement('script');\n    s.src = '/console/script.js';\n    s.onload = function () {\n      // The console mounts its own full-screen surface; the splash goes.\n      if (document.getElementById('gpa-root-host')) boot.remove();\n      else { msg.textContent = 'The console didn’t start.'; retry.hidden = false; }\n    };\n    s.onerror = function () {\n      s.remove();\n      msg.textContent = navigator.onLine === false\n        ? 'You’re offline and the console isn’t saved on this device yet. Connect once, then it opens offline too.'\n        : 'Couldn’t load the console. Check your connection and try again.';\n      retry.hidden = false;\n    };\n    document.head.appendChild(s);\n  }\n  retry.addEventListener('click', start);\n\n  try { var seen = localStorage.getItem('agent-console-app.install-seen') === '1'; } catch (e) { seen = true; }\n  if (!standalone && iPhoneSafari && !seen) {\n    msg.textContent = 'Add Saints Service to your Home Screen to use it as an app.';\n    install.hidden = false;\n    document.getElementById('install-continue').addEventListener('click', function () {\n      try { localStorage.setItem('agent-console-app.install-seen', '1'); } catch (e) { /* private mode */ }\n      start();\n    });\n  } else {\n    start();\n  }\n})();\n"},"/console/icon-180.png":{"type":"image/png","body":"","base64":true},"/console/icon-192.png":{"type":"image/png","body":"","base64":true},"/console/icon-512.png":{"type":"image/png","body":"","base64":true},"/console/icon-maskable-512.png":{"type":"image/png","body":"","base64":true},"/console/":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n<meta name=\"apple-mobile-web-app-title\" content=\"Saints Service\">\n<meta name=\"application-name\" content=\"Saints Service\">\n<meta name=\"theme-color\" content=\"#0b0c0f\">\n<meta name=\"description\" content=\"Saints Service as a full-screen app: Ask AI, Chat, Music, Games, Study, Notes, Eaglercraft and more.\">\n<link rel=\"manifest\" href=\"/console/manifest.webmanifest\">\n<link rel=\"apple-touch-icon\" href=\"/console/icon-180.png\">\n<link rel=\"icon\" type=\"image/png\" href=\"/console/icon-192.png\">\n<link rel=\"stylesheet\" href=\"/console/app.css\">\n<title>Saints Service</title>\n<script src=\"/console/app.js\" defer></script>\n</head>\n<body>\n<main class=\"boot\" id=\"boot\" aria-live=\"polite\">\n  <img src=\"/console/icon-192.png\" alt=\"\" width=\"72\" height=\"72\">\n  <h1>Saints Service</h1>\n  <p id=\"boot-msg\">Loading…</p>\n  <button id=\"boot-retry\" type=\"button\" hidden>Try again</button>\n  <section class=\"install\" id=\"install\" hidden>\n    <h2>Install on your iPhone</h2>\n    <ol>\n      <li>Open this page in <strong>Safari</strong>.</li>\n      <li>Tap the <strong>Share</strong> button.</li>\n      <li>Choose <strong>Add to Home Screen</strong>.</li>\n      <li>Keep <strong>Open as Web App</strong> on, then tap <strong>Add</strong>.</li>\n    </ol>\n    <button id=\"install-continue\" type=\"button\">Continue in the browser</button>\n  </section>\n</main>\n<noscript><p class=\"boot\">Saints Service needs JavaScript.</p></noscript>\n</body>\n</html>\n"},"/console/manifest.webmanifest":{"type":"application/manifest+json","body":"{\n  \"id\": \"/console/\",\n  \"name\": \"Saints Service\",\n  \"short_name\": \"Console\",\n  \"description\": \"Ask AI, Chat, Music, Games, Study, Notes, Eaglercraft and more, as a full-screen app.\",\n  \"start_url\": \"/console/\",\n  \"scope\": \"/console/\",\n  \"display\": \"standalone\",\n  \"orientation\": \"any\",\n  \"background_color\": \"#0b0c0f\",\n  \"theme_color\": \"#0b0c0f\",\n  \"icons\": [\n    { \"src\": \"/console/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/console/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/console/icon-maskable-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"maskable\" }\n  ]\n}\n"},"/console/sw.js":{"type":"text/javascript; charset=utf-8","body":"// Offline shell and owner notifications for the Saints Service app. Only the\n// app's own files are cached (shell, icons and the console script); API\n// calls, chat, AI answers and anything from other origins always go to the\n// network. Push messages come from the Worker (web/console/push.js).\nconst CACHE = 'agent-console-app-v3';\nconst SHELL = ['/console/', '/console/app.css', '/console/app.js', '/console/manifest.webmanifest',\n  '/console/icon-180.png', '/console/icon-192.png', '/console/icon-512.png', '/console/icon-maskable-512.png'];\nconst SCRIPT = '/console/script.js';\nself.addEventListener('install', (event) => {\n  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(SHELL)).then(() => self.skipWaiting()));\n});\nself.addEventListener('activate', (event) => {\n  event.waitUntil(caches.keys()\n    .then((keys) => Promise.all(keys.filter((k) => k.startsWith('agent-console-app-') && k !== CACHE).map((k) => caches.delete(k))))\n    .then(() => self.clients.claim()));\n});\nself.addEventListener('fetch', (event) => {\n  const url = new URL(event.request.url);\n  if (event.request.method !== 'GET' || url.origin !== self.location.origin || url.search) return;\n  if (!SHELL.includes(url.pathname) && url.pathname !== SCRIPT) return;\n  // Network first, so every launch gets the latest console; the cached copy\n  // is the offline fallback.\n  event.respondWith(fetch(event.request).then((res) => {\n    if (res.ok) { const copy = res.clone(); event.waitUntil(caches.open(CACHE).then((c) => c.put(event.request, copy))); }\n    return res;\n  }).catch(() => caches.match(event.request).then((hit) => hit || Response.error())));\n});\n\nself.addEventListener('push', (event) => {\n  let m = {};\n  try { m = event.data ? event.data.json() : {}; } catch (e) { m = { body: event.data ? event.data.text() : '' }; }\n  const title = m.title || 'Saints Service';\n  // \"Who's online\" carries the count for the app icon badge (iOS 16.4+).\n  if (typeof m.badge === 'number' && self.navigator && self.navigator.setAppBadge) {\n    try { (m.badge > 0 ? self.navigator.setAppBadge(m.badge) : self.navigator.clearAppBadge()).catch(() => {}); } catch (e) { /* unsupported */ }\n  }\n  event.waitUntil(self.registration.showNotification(title, {\n    body: m.body || '',\n    tag: m.tag || undefined,\n    icon: '/console/icon-192.png',\n    badge: '/console/icon-192.png',\n    timestamp: m.ts || Date.now(),\n    silent: m.silent === true,\n    // A newer message for the same chat replaces the old one and still alerts.\n    renotify: !!m.tag,\n    data: { url: typeof m.url === 'string' && m.url.startsWith('/console/') ? m.url : '/console/' }\n  }));\n});\n// Tapping a notification opens the app on the right tab (chat, admin…).\nself.addEventListener('notificationclick', (event) => {\n  event.notification.close();\n  const url = (event.notification.data && event.notification.data.url) || '/console/';\n  event.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((list) => {\n    const app = list.find((c) => new URL(c.url).pathname.startsWith('/console/'));\n    if (app) { app.postMessage({ type: 'agent-console-open', url }); return app.focus(); }\n    return self.clients.openWindow(url);\n  }));\n});\n"}};
